def transform(grid: list[list[int]]) -> list[list[int]]:
    """
    The transformation rule is based on the interaction between 'seed' cells (value 4)
    and other non-zero cells (1, 2, 3).

    For every cell (r, c) with value 4:
    1. Check the four cardinal directions (up, down, left, right).
    2. In each direction, look for the first non-zero cell (1, 2, or 3).
    3. If a non-zero cell is found in a direction (dr, dc), it 'triggers' a line 
       of color 7 in the OPPOSITE direction (-dr, -dc).
    4. The line of color 7 starts from the cell adjacent to the seed and extends 
       for 3 cells (or until the boundary).
    5. Additionally, cells with value 2 in the original grid are preserved 
       unless overwritten by the color 7.
    """
    rows = len(grid)
    cols = len(grid[0])
    output = np.zeros((rows, cols), dtype=int)

    # Preserve original 2s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                output[r][c] = 2

    # Process seeds (value 4)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 4:
                for dr, dc in directions:
                    # Look for a non-zero cell in this direction
                    found = False
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] != 0:
                            found = True
                            break
                        nr += dr
                        nc += dc

                    # If found, draw a line of 7s in the opposite direction
                    if found:
                        odr, odc = -dr, -dc
                        for i in range(1, 4):
                            tr, tc = r + i * odr, c + i * odc
