    if not non_zero_coords:
        return output

    # Group non-zero pixels into connected components (4-connectivity)
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    components = []

    for r, c in non_zero_coords:
        if not visited[r][c]:
            component = []
            stack = [(r, c)]
            visited[r][c] = True
            while stack:
                curr_r, curr_c = stack.pop()
                component.append((curr_r, curr_c))
                for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and \
                       grid[nr][nc] != 0 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        stack.append((nr, nc))
            components.append(component)

    # For each component, find its bounding box and draw a border of 9s
    for comp in components:
        min_r = min(p[0] for p in comp)
        max_r = max(p[0] for p in comp)
        min_c = min(p[1] for p in comp)
        max_c = max(p[1] for p in comp)

        # The border extends 1 pixel outside the bounding box
        # Top and bottom edges
        for c in range(min_c - 1, max_c + 2):
            if 0 <= min_r - 1 < rows and 0 <= c < cols:
                if output[min_r - 1][c] == 0:
                    output[min_r - 1][c] = 9
            if 0 <= max_r + 1 < rows and 0 <= c < cols:
                if output[max_r + 1][c] == 0:
                    output[max_r + 1][c] = 9

        # Left and right edges
        for r in range(min_r - 1, max_r + 2):
            if 0 <= r < rows and 0 <= min_c - 1 < cols:
                if output[r][min_c - 1] == 0:
                    output[r][min_c - 1] = 9
            if 0 <= r < rows and 0 <= max_c + 1 < cols:
                if output[r][max_c + 1] == 0:
                    output[r][max_c + 1] = 9

    return output
