def transform(grid: list[list[int]]) -> list[list[int]]:
    """
    The transformation rule:
    For each unique color C (excluding 0):
    1. Find all coordinates (r, c) where grid[r][c] == C.
    2. Find the minimum row (r_min) and minimum column (c_min) among these coordinates.
    3. For every coordinate (r, c) of color C, place color C in the output grid at (r - r_min, c - c_min).
    4. If multiple colors map to the same cell, the color processed last takes precedence.
    """
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])
    out_grid = [[0 for _ in range(cols)] for _ in range(rows)]

    # Find all unique colors except 0
    unique_colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0:
                unique_colors.add(grid[r][c])

    # Process colors in numerical order to be consistent
    for color in sorted(list(unique_colors)):
        coords = []
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == color:
                    coords.append((r, c))

        if not coords:
            continue

        # Find the minimum row and column for this color
        r_min = min(r for r, c in coords)
        c_min = min(c for r, c in coords)

        # Shift all coordinates of this color by (r_min, c_min)
        for r, c in coords:
            new_r, new_c = r - r_min, c - c_min
            if 0 <= new_r < rows and 0 <= new_c < cols:
                out_grid[new_r][new_c] = color

    return out_grid
